ALTER TABLE s2_combat_cast_command ADD cone_direction INT NULL;
ALTER TABLE s2_combat_cast_command DROP CHECK ck_s236_1;
ALTER TABLE s2_combat_cast_command ADD CONSTRAINT ck_s236_1 CHECK (OCTET_LENGTH(combat_id) = 16 AND (ORD(SUBSTRING(combat_id, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(combat_id, 9, 1)) & 192) = 128 AND event_sequence BETWEEN 1 AND 128 AND command_index = 0 AND target_count BETWEEN 0 AND 16 AND (material_item_id IS NULL OR (OCTET_LENGTH(material_item_id) = 16 AND (ORD(SUBSTRING(material_item_id, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(material_item_id, 9, 1)) & 192) = 128)) AND casting_type IN (_binary'character.spellcasting', _binary'character.wizard_spellcasting') AND OCTET_LENGTH(casting_module) BETWEEN 1 AND 64 AND OCTET_LENGTH(casting_key) BETWEEN 1 AND 128 AND spell_type = _binary'adventure.spell' AND OCTET_LENGTH(spell_module) BETWEEN 1 AND 64 AND OCTET_LENGTH(spell_key) BETWEEN 1 AND 128 AND slot_level BETWEEN 1 AND 9 AND (target_cast_frame_key IS NULL OR (OCTET_LENGTH(target_cast_frame_key) = 16 AND (ORD(SUBSTRING(target_cast_frame_key, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(target_cast_frame_key, 9, 1)) & 192) = 128)));
ALTER TABLE s2_combat_cast_command ADD CONSTRAINT ck_s242_command_area CHECK ((cone_direction IS NULL AND target_count BETWEEN 1 AND 3) OR (cone_direction IS NOT NULL AND cone_direction BETWEEN 0 AND 7 AND target_count=0 AND casting_type=_binary'character.wizard_spellcasting' AND material_item_id IS NULL AND target_cast_frame_key IS NULL AND slot_level BETWEEN 1 AND 3));

ALTER TABLE s2_combat_cast ADD cone_direction INT NULL;
ALTER TABLE s2_combat_cast DROP CHECK ck_s236_5;
ALTER TABLE s2_combat_cast ADD CONSTRAINT ck_s236_5 CHECK (OCTET_LENGTH(combat_id) = 16 AND (ORD(SUBSTRING(combat_id, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(combat_id, 9, 1)) & 192) = 128 AND event_sequence BETWEEN 1 AND 128 AND cast_index BETWEEN 0 AND 1023 AND target_count BETWEEN 0 AND 16 AND healing_die_count BETWEEN 0 AND 20 AND OCTET_LENGTH(frame_key) = 16 AND (ORD(SUBSTRING(frame_key, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(frame_key, 9, 1)) & 192) = 128 AND OCTET_LENGTH(actor_id) = 16 AND (ORD(SUBSTRING(actor_id, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(actor_id, 9, 1)) & 192) = 128 AND slot_level BETWEEN 1 AND 9 AND (material_item_id IS NULL OR (OCTET_LENGTH(material_item_id) = 16 AND (ORD(SUBSTRING(material_item_id, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(material_item_id, 9, 1)) & 192) = 128)) AND (effect_key IS NULL OR (OCTET_LENGTH(effect_key) = 16 AND (ORD(SUBSTRING(effect_key, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(effect_key, 9, 1)) & 192) = 128)) AND healing_modifier BETWEEN -5 AND 10 AND requested_healing BETWEEN 0 AND 65535 AND applied_healing BETWEEN 0 AND requested_healing AND casting_type IN (_binary'character.spellcasting', _binary'character.wizard_spellcasting') AND OCTET_LENGTH(casting_module) BETWEEN 1 AND 64 AND OCTET_LENGTH(casting_key) BETWEEN 1 AND 128 AND spell_type = _binary'adventure.spell' AND OCTET_LENGTH(spell_module) BETWEEN 1 AND 64 AND OCTET_LENGTH(spell_key) BETWEEN 1 AND 128 AND slot_type = _binary'character.resource' AND OCTET_LENGTH(slot_module) BETWEEN 1 AND 64 AND OCTET_LENGTH(slot_key) BETWEEN 1 AND 128 AND phase IN (_binary'BEFORE', _binary'AFTER') AND flow_index BETWEEN 0 AND 127 AND cast_status IN (_binary'PENDING', _binary'HELD', _binary'RESOLVED', _binary'COUNTERED', _binary'INTERRUPTED') AND (target_cast_frame_key IS NULL OR (OCTET_LENGTH(target_cast_frame_key) = 16 AND (ORD(SUBSTRING(target_cast_frame_key, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(target_cast_frame_key, 9, 1)) & 192) = 128)) AND (ready_key IS NULL OR (OCTET_LENGTH(ready_key) = 16 AND (ORD(SUBSTRING(ready_key, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(ready_key, 9, 1)) & 192) = 128)) AND (cast_status=_binary'RESOLVED' OR (effect_key IS NULL AND healing_die_count=0 AND requested_healing=0 AND applied_healing=0)));
ALTER TABLE s2_combat_cast ADD CONSTRAINT ck_s242_cast_area CHECK (((cone_direction IS NULL AND target_count BETWEEN 1 AND 3) OR (cone_direction IS NOT NULL AND cone_direction BETWEEN 0 AND 7 AND target_count=0 AND casting_type=_binary'character.wizard_spellcasting' AND material_item_id IS NULL AND target_cast_frame_key IS NULL AND slot_level BETWEEN 1 AND 3 AND ready_key IS NULL)) AND (cast_status<>_binary'INTERRUPTED' OR cone_direction IS NOT NULL));

ALTER TABLE s2_combat_save_damage_batch MODIFY action_rule_module VARBINARY(64) NULL;
ALTER TABLE s2_combat_save_damage_batch MODIFY action_rule_type VARBINARY(40) NULL;
ALTER TABLE s2_combat_save_damage_batch MODIFY action_rule_key VARBINARY(128) NULL;
