ALTER TABLE s2_combat_save_damage_batch MODIFY action_key VARBINARY(64) NULL;
ALTER TABLE s2_combat_save_damage_batch DROP CHECK ck_c40_4;
ALTER TABLE s2_combat_save_damage_batch ADD CONSTRAINT ck_c40_4 CHECK (event_sequence BETWEEN 1 AND 128 AND phase IN (_binary'BEFORE', _binary'AFTER') AND OCTET_LENGTH(combat_id) = 16 AND (ORD(SUBSTRING(combat_id, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(combat_id, 9, 1)) & 192) = 128 AND batch_index BETWEEN 0 AND 127 AND OCTET_LENGTH(batch_key) = 16 AND (ORD(SUBSTRING(batch_key, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(batch_key, 9, 1)) & 192) = 128 AND OCTET_LENGTH(frame_key) = 16 AND (ORD(SUBSTRING(frame_key, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(frame_key, 9, 1)) & 192) = 128 AND OCTET_LENGTH(source_id) = 16 AND (ORD(SUBSTRING(source_id, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(source_id, 9, 1)) & 192) = 128 AND OCTET_LENGTH(release_operation_id) = 16 AND (ORD(SUBSTRING(release_operation_id, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(release_operation_id, 9, 1)) & 192) = 128 AND origin_x BETWEEN -10000 AND 10000 AND origin_y BETWEEN -10000 AND 10000 AND direction BETWEEN 0 AND 7 AND (shared_roll_key IS NULL OR (OCTET_LENGTH(shared_roll_key) = 16 AND (ORD(SUBSTRING(shared_roll_key, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(shared_roll_key, 9, 1)) & 192) = 128)) AND ((action_rule_module IS NULL AND action_rule_type IS NULL AND action_rule_key IS NULL AND action_collection IS NULL AND action_module IS NULL AND action_key IS NULL) OR (action_rule_module IS NOT NULL AND action_rule_type IS NOT NULL AND action_rule_key IS NOT NULL AND action_collection IS NOT NULL AND action_module IS NOT NULL AND action_key IS NOT NULL AND OCTET_LENGTH(action_rule_module) BETWEEN 1 AND 64 AND REGEXP_LIKE(CONVERT(action_rule_module USING latin1), '^[a-z][a-z0-9_]*$', 'c') AND action_rule_type = _binary'adventure.monster' AND OCTET_LENGTH(action_rule_key) BETWEEN 1 AND 128 AND action_collection = _binary'actions' AND OCTET_LENGTH(action_module) BETWEEN 1 AND 64 AND REGEXP_LIKE(CONVERT(action_module USING latin1), '^[a-z][a-z0-9_]*$', 'c') AND OCTET_LENGTH(action_key) BETWEEN 1 AND 64)) AND batch_status IN (_binary'ROLLED', _binary'COMPLETED', _binary'NO_TARGETS') AND released_turn_number BETWEEN 1 AND 8192 AND roster_version BETWEEN 0 AND 127 AND candidate_count BETWEEN 2 AND 64 AND target_count BETWEEN 0 AND 64 AND die_count IN (0,3,4,5,6) AND check_count BETWEEN 0 AND 128 AND packet_count BETWEEN 0 AND 64 AND obligation_count BETWEEN 0 AND 64 AND ((batch_status=_binary'NO_TARGETS' AND target_count=0 AND shared_roll_key IS NULL AND die_count=0 AND raw_total IS NULL AND effective_total IS NULL) OR (batch_status<>_binary'NO_TARGETS' AND target_count>0 AND shared_roll_key IS NOT NULL AND die_count BETWEEN 3 AND 6 AND raw_total IS NOT NULL AND effective_total IS NOT NULL AND raw_total BETWEEN die_count AND die_count*6 AND effective_total=raw_total)));

ALTER TABLE s2_combat_breath_check DROP CHECK ck_c40_8;
ALTER TABLE s2_combat_breath_check ADD CONSTRAINT ck_c40_8 CHECK (event_sequence BETWEEN 1 AND 128 AND phase IN (_binary'BEFORE', _binary'AFTER') AND OCTET_LENGTH(combat_id) = 16 AND (ORD(SUBSTRING(combat_id, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(combat_id, 9, 1)) & 192) = 128 AND batch_index BETWEEN 0 AND 127 AND check_index BETWEEN 0 AND 127 AND (first_d20 IS NULL OR first_d20 BETWEEN 1 AND 20) AND (second_d20 IS NULL OR second_d20 BETWEEN 1 AND 20) AND advantage IN (0,1) AND disadvantage IN (0,1) AND (blessing_effect_key IS NULL OR (OCTET_LENGTH(blessing_effect_key) = 16 AND (ORD(SUBSTRING(blessing_effect_key, 7, 1)) & 240) = 64 AND (ORD(SUBSTRING(blessing_effect_key, 9, 1)) & 192) = 128)) AND success IN (0,1) AND purpose IN (_binary'BREATH_DEX', _binary'SPELL_DEX', _binary'CONCENTRATION_CON') AND check_mode IN (_binary'ROLL', _binary'AUTO_FAILURE') AND target_ordinal BETWEEN 0 AND 63 AND ability_modifier BETWEEN -5 AND 10 AND proficiency_bonus BETWEEN 0 AND 6 AND difficulty_class BETWEEN 0 AND 32767 AND ((blessing_effect_key IS NULL AND blessing_d4 IS NULL) OR (blessing_effect_key IS NOT NULL AND blessing_d4 IS NOT NULL AND blessing_d4 BETWEEN 1 AND 4)) AND ((check_mode=_binary'AUTO_FAILURE' AND first_d20 IS NULL AND second_d20 IS NULL AND success=0) OR (check_mode=_binary'ROLL' AND first_d20 IS NOT NULL AND ((advantage=disadvantage AND second_d20 IS NULL) OR (advantage<>disadvantage AND second_d20 IS NOT NULL)))));

CREATE TABLE s2_combat_spell_damage_source (
    combat_id VARBINARY(16) NOT NULL,
    event_sequence INT NOT NULL,
    phase VARBINARY(6) NOT NULL,
    batch_index INT NOT NULL,
    cast_frame_key VARBINARY(16) NOT NULL,
    spell_module VARBINARY(64) NOT NULL,
    spell_type VARBINARY(40) NOT NULL,
    spell_key VARBINARY(128) NOT NULL,
    slot_level INT NOT NULL,
    ability_modifier INT NOT NULL,
    proficiency_bonus INT NOT NULL,
    PRIMARY KEY (combat_id,event_sequence,phase,batch_index),
    CONSTRAINT fk_s242_spell_batch FOREIGN KEY (combat_id,event_sequence,phase,batch_index)
        REFERENCES s2_combat_save_damage_batch (combat_id,event_sequence,phase,batch_index) ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT ck_s242_spell_source CHECK (event_sequence BETWEEN 1 AND 128 AND phase IN (_binary'BEFORE',_binary'AFTER')
        AND batch_index BETWEEN 0 AND 127 AND OCTET_LENGTH(cast_frame_key)=16
        AND (ORD(SUBSTRING(cast_frame_key,7,1)) & 240)=64 AND (ORD(SUBSTRING(cast_frame_key,9,1)) & 192)=128
        AND OCTET_LENGTH(spell_module) BETWEEN 1 AND 64 AND REGEXP_LIKE(CONVERT(spell_module USING latin1),'^[a-z][a-z0-9_]*$','c')
        AND spell_type=_binary'adventure.spell' AND OCTET_LENGTH(spell_key) BETWEEN 1 AND 128
        AND slot_level BETWEEN 1 AND 3 AND ability_modifier BETWEEN -5 AND 10 AND proficiency_bonus BETWEEN 2 AND 3)
) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_bin;

DELIMITER $$
CREATE TRIGGER s2_combat_spell_damage_source_insert BEFORE INSERT ON s2_combat_spell_damage_source FOR EACH ROW
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM s2_combat_save_damage_batch b
        JOIN s2_combat_cast c ON c.combat_id=b.combat_id AND c.event_sequence=b.event_sequence AND c.phase=b.phase
        JOIN s2_combat_frame f ON f.combat_id=b.combat_id AND f.event_sequence=b.event_sequence AND f.phase=b.phase AND f.frame_key=b.frame_key
        WHERE b.combat_id=NEW.combat_id AND b.event_sequence=NEW.event_sequence AND b.phase=NEW.phase AND b.batch_index=NEW.batch_index
            AND b.action_rule_module IS NULL AND b.source_id=c.actor_id AND c.frame_key=NEW.cast_frame_key
            AND c.spell_module=NEW.spell_module AND c.spell_type=NEW.spell_type AND c.spell_key=NEW.spell_key
            AND c.slot_level=NEW.slot_level AND c.cone_direction=b.direction AND c.ready_key IS NULL
            AND f.parent_frame_key=c.frame_key AND f.frame_kind=_binary'SAVE_DAMAGE' AND f.owner_key=b.batch_key
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Schema2 spell save-damage source mismatch';
    END IF;
END$$
CREATE TRIGGER s2_combat_spell_damage_source_update BEFORE UPDATE ON s2_combat_spell_damage_source FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable schema2 spell save-damage source';
END$$
CREATE TRIGGER s2_combat_spell_damage_source_delete BEFORE DELETE ON s2_combat_spell_damage_source FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable schema2 spell save-damage source';
END$$
DELIMITER ;
